# Compute recovery rate by cohort from df
import pandas as pd

# Identify likely cohort and recovery columns robustly
cols = list(df.columns)
lower_map = {c.lower(): c for c in cols}

# guess columns
cohort_col = None
for cand in ['cohort', 'group', 'arm', 'treatment_group', 'trial_group']:
    if cand in lower_map:
        cohort_col = lower_map[cand]
        break

recovered_col = None
for cand in ['recovered', 'recovery', 'outcome_recovered', 'success', 'recovered_count']:
    if cand in lower_map:
        recovered_col = lower_map[cand]
        break

total_col = None
for cand in ['total', 'n', 'count', 'patients', 'sample_size']:
    if cand in lower_map:
        total_col = lower_map[cand]
        break

# If data is one row per patient, infer recovered from outcome column
if cohort_col is None:
    raise ValueError(f'Could not find cohort column in {cols}')

if recovered_col and total_col:
    agg = df.groupby(cohort_col, dropna=False).agg(recovered=(recovered_col, 'sum'), total=(total_col, 'sum')).reset_index()
else:
    # find outcome column for row-level data
    outcome_col = None
    for cand in ['outcome', 'status', 'result', 'recovery_status']:
        if cand in lower_map:
            outcome_col = lower_map[cand]
            break
    if outcome_col is None:
        raise ValueError(f'Could not infer recovered/total or outcome column in {cols}')
    # define recovered as values containing 'recover' or 'yes' or 1
    s = df[outcome_col].astype(str).str.lower()
    recovered_mask = s.str.contains('recover|yes|true|1')
    agg = df.assign(_recovered=recovered_mask).groupby(cohort_col, dropna=False).agg(recovered=('_recovered', 'sum'), total=('_recovered', 'size')).reset_index()

agg['rate'] = agg['recovered'] / agg['total']
row = agg.loc[agg['rate'].idxmax()]
print({'cohort': row[cohort_col], 'rate': round(float(row['rate']), 2), 'evidence': f"{row[cohort_col]}: {int(row['recovered'])}/{int(row['total'])}"})

